<h1><?= te('Your notifications') ?></h1><p class="sub"><?= te('Notifications are available on your mobile portal. Background mobile push is not configured.') ?></p><div class="card"><?php foreach($notifications as $n): ?><form class="row" method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$n['id'] ?>"><a href="<?= e($n['target']) ?>"><?= e($n['message']) ?></a><span><?= e($n['created_at']) ?></span><?php if(!$n['read_at']): ?><button class="btn sm"><?= te('Mark read') ?></button><?php endif; ?></form><?php endforeach; ?></div><div class="card"><h2><?= te('Notifications while the platform is open') ?></h2><button class="btn" type="button" onclick="if('Notification' in window) Notification.requestPermission()"><?= te('Enable browser notifications') ?></button><p class="muted"><?= te('This requires browser support and HTTPS. Notifications are checked every 30 seconds while the platform is open; background push requires a separate service.') ?></p></div>